#include "cloudmoon_ws.h"
#include <string.h>
int cm_ws_encode_client_frame(uint8_t*out,size_t cap,uint8_t opcode,int fin,const uint8_t*payload,size_t len,const uint8_t key[4]){size_t h,i,total;if(!out||!key||(len&&!payload)||opcode>15)return -1;if(opcode>=8&&(!fin||len>125))return -1;h=len<126?6:(len<=65535?8:14);if(len>0x7fffffffffffffffULL||cap<h||len>cap-h)return -1;total=h+len;out[0]=(uint8_t)((fin?128:0)|opcode);if(len<126)out[1]=(uint8_t)(128|len);else if(len<=65535){out[1]=128|126;out[2]=(uint8_t)(len>>8);out[3]=(uint8_t)len;}else{out[1]=128|127;for(i=0;i<8;i++)out[2+i]=(uint8_t)((uint64_t)len>>(56-i*8));}memcpy(out+h-4,key,4);for(i=0;i<len;i++)out[h+i]=payload[i]^key[i&3];return (int)total;}
int cm_ws_decode_server_frame(const uint8_t*f,size_t flen,cm_ws_frame_info_t*info,uint8_t*out,size_t out_cap){uint64_t len;size_t h=2,i;uint8_t b;if(!f||!info||flen<2)return -1;if((f[0]&0x70)!=0||(f[1]&0x80)!=0)return -1;info->fin=(f[0]&0x80)!=0;info->opcode=f[0]&15;b=f[1]&127;if(b<126)len=b;else if(b==126){if(flen<4)return -1;len=((uint64_t)f[2]<<8)|f[3];h=4;if(len<126)return -1;}else{if(flen<10||(f[2]&128))return -1;len=0;for(i=0;i<8;i++)len=(len<<8)|f[2+i];h=10;if(len<=65535)return -1;}if(len>(uint64_t)(flen-h)||len>out_cap||(len&&!out))return -1;if(info->opcode>=8&&(!info->fin||len>125))return -1;if(info->opcode>10||info->opcode==3||info->opcode==4||info->opcode==5||info->opcode==6||info->opcode==7)return -1;info->payload_len=(size_t)len;if(len)memcpy(out,f+h,(size_t)len);return (int)(h+(size_t)len);}
